mapper.select:
SELECT f.id, f.event_cursor AS eventCursor, f.request_started_at AS requestStartedAt, f.request_id AS requestId, CASE WHEN f.user_id=0 THEN '已注销成员' ELSE COALESCE(NULLIF(usr.nickname,''),usr.username,CONCAT('成员 ',f.user_id)) END AS memberLabel, COALESCE(CONCAT(k.name,' (',k.key_prefix,')'),CONCAT('API Key ',f.api_key_id)) AS apiKeyLabel, COALESCE(s.name,CONCAT('服务 ',f.service_id)) AS serviceLabel, f.model,f.status,f.usage_source AS usageSource, f.input_tokens AS inputTokens,f.output_tokens AS outputTokens,f.total_tokens AS totalTokens, f.cost_status AS costStatus,f.estimated_cost_fen AS estimatedCostFen,f.currency FROM () f LEFT JOIN t_user usr ON usr.user_id=f.user_id LEFT JOIN t_api_key k ON k.api_key_id=f.api_key_id AND k.tenant_id=f.tenant_id LEFT JOIN t_llm_service s ON s.service_id=f.service_id AND s.tenant_id=f.tenant_id
WHERE f.request_started_at > #{afterTime} OR (f.request_started_at=#{afterTime} AND f.event_cursor > #{afterEvent})
ORDER BY f.request_started_at,f.event_cursor LIMIT #{limit}
